#pragma once

// Symbols drawn as 1-bit bitmaps (generated by tools/icongen/icongen.py;
// own drawings, no third-party icons).

#include <cstddef>
#include <cstdint>

#include "ui/canvas.h"

namespace ui {

// Rows top to bottom, each padded to whole bytes, most significant bit =
// leftmost pixel, set bit = drawn.
struct Icon {
  uint8_t width;
  uint8_t height;
  const uint8_t* bits;
};

void drawIcon(Canvas& canvas, int x, int y, const Icon& icon, Color color = Color::kBlack);

enum class WeatherIcon {
  kSun,
  kPartlyCloudy,
  kCloudy,
  kRain,
  kFog,
  kMoon,  // clear night
  kPartlyCloudyNight,
  kSnow,
  kThunder,
  // Only for the days of the weather column (2026-10-29); the band shows
  // the umbrella for these. kRain is moderate rain (two strokes).
  kRainLight,     // one stroke
  kRainHeavy,     // three strokes
  kShowers,       // sun, cloud and rain
  kFreezingRain,  // rain and a snow star (also sleet)
  // W1 (2026-11-22). kSnow (three stars) is also the heavy snow of the
  // columns; kSnowHeavy differs from it only in the band (three flakes).
  kSnowLight,        // one star; in the band the flake of kSnow
  kSnowHeavy,        // columns: as kSnow
  kShowersLight,     // sun, cloud, one stroke (80); kShowers is 82
  kShowersModerate,  // two strokes (81)
  kThunderHail,      // bolt and hail grains (96, 99)
  // Only in the band, from the storm threshold (W1).
  kWindSock,
  kStormRain,  // windsock with driven rain
  kSnowWind,   // snowflake with wind lines
};

// Weather symbol in one of the generated sizes (44 and 30 px); other sizes give the
// nearest one.
const Icon& weatherIcon(WeatherIcon kind, int size);

// Large weather picture for the band, kBandIconWidth x kBandIconHeight, drawn
// in this size. Rain is an umbrella with two, four or six drops (light,
// moderate, heavy; showers and freezing rain as moderate rain).
inline constexpr int kBandIconWidth = 156;
inline constexpr int kBandIconHeight = 132;
const Icon& bandIcon(WeatherIcon kind);

// Calendar sheet for all-day events, 15 px.
extern const Icon kCalendarIcon;
// Location pin for places (weather column), 16 px.
extern const Icon kPinIcon;
// Round stop sign with an H for stations (departure column), 16 px.
extern const Icon kStationIcon;

// Generated table (icons_data.cpp).
struct WeatherIconEntry {
  WeatherIcon kind;
  Icon icon;
};
extern const WeatherIconEntry kWeatherIcons[];
extern const size_t kWeatherIconCount;
extern const WeatherIconEntry kBandIcons[];
extern const size_t kBandIconCount;

}  // namespace ui
